class Solution:

	def CountPS(self, S, N):
		count = 0
		dp = [[False] * N for _ in range(N)]
		for i in range(N):
			dp[i][i] = True
		for i in range(N - 1):
			if S[i] == S[i + 1]:
				dp[i][i + 1] = True
				count += 1
		for k in range(3, N + 1):
			for i in range(N - k + 1):
				j = i + k - 1
				if S[i] == S[j] and dp[i + 1][j - 1]:
					dp[i][j] = True
					count += 1
		return count
